html_filename = "forex_factory.html"


def get_calender(link, html_filename):
    response = requests.get(link)
    filename = Path(BASE_DIR, html_filename)
    temp_file = f"{filename}.tmp"
    temp_file = Path(BASE_DIR, temp_file)
    try:
        with open(temp_file, "w", encoding="utf-8") as file:
            file.write(response.text)
        os.replace(temp_file, filename)
        return True
    except Exception as e:
        print(e)
        if os.path.exists(Path(BASE_DIR, temp_file)):
            os.remove(temp_file)
            return False


def get_calendar_info(dates: List, calendarCell: ResultSet[Tag], impact: str):
    date: str = calendarCell[0].text.strip()
    country = calendarCell[2].find("i")["title"]
    currency = calendarCell[3].text.strip()
    info = calendarCell[4].text.strip()
    previous = calendarCell[6].text.strip()
    concensus = calendarCell[7].text.strip()
    actual = calendarCell[8].text.strip()
    if date.split(", ")[0] not in dates:
        dates.append(date.split(", ")[0])
    return f"{impact.title()}: {date} {country} {currency} {info}\nPrevious: {previous} Consensus: {concensus} Actual: {actual}"


def get_events(calendarData: List[Dict]):
    saved_calendar = {}
    low_impact = []
    medium_impact = []
    high_impact = []
    dates = []
    for calendar in reversed(calendarData):
        currentDate = datetime.strptime(calendar['Date'], "%Y.%m.%d %H:%M:%S").strftime("%b %d, %H:%M")
        date =  datetime.strptime(calendar['Date'], "%Y.%m.%d %H:%M:%S").strftime("%b %d")
        if date not in dates:
            dates.append(date)
        if calendar['Impact'].lower() == 'low':
            event_text = f"{currentDate} | {calendar['Currency']} | {calendar['Name']}\n\nActual{calendar['Actual']} | Forecast:{calendar['Forecast']} | Previous:{calendar['Previous']}"
            low_impact.append(event_text)
        elif calendar['Impact'].lower() == 'medium':
            event_text = f"{currentDate} | {calendar['Currency']} | {calendar['Name']}\n\nActual{calendar['Actual']} | Forecast:{calendar['Forecast']} | Previous:{calendar['Previous']}"
            medium_impact.append(event_text)
        elif calendar['Impact'].lower() == 'high':
            event_text = f"{currentDate} | {calendar['Currency']} | {calendar['Name']}\n\nActual{calendar['Actual']} | Forecast:{calendar['Forecast']} | Previous:{calendar['Previous']}"
            high_impact.append(event_text)
    saved_calendar["refresh_date"] = datetime.now().isoformat()
    saved_calendar["dates"] = dates
    saved_calendar["low_impact"] = low_impact
    saved_calendar["medium_impact"] = medium_impact
    saved_calendar["high_impact"] = high_impact
    return saved_calendar


def main(data:List[Dict]|None = None):
    api_key = settings.CALENDER_API_KEY
    print(api_key)
    BASE_DIR = Path(__file__).resolve().parent
    link = "https://www.jblanked.com/news/api/forex-factory/calendar/week/"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Api-Key {api_key}",
    }
    if data is None:
        response = requests.get(link, headers=headers)
        print(headers)
        calendarData = response.json()
        pprint(response.json())

    temp_file = Path(BASE_DIR, "calendar.json.tmp")
    real_file = Path(BASE_DIR, "calendar.json")
    try:
        calendar = get_events(calendarData=calendarData if data is None else data)
        with open(temp_file, "w") as file:
            file.write(json.dumps(calendar, indent=3))
        os.replace(temp_file, real_file)
    except Exception as e:
        print(e)
        if temp_file.exists():
            os.remove(temp_file)

    # else:
